-- Vyapar parity Phase 2 (sale enhancements). Generated by drizzle-kit, then the RLS block below appended by hand.
-- Additive only: every new column is nullable or has a default, so code from before this migration still runs.
CREATE TABLE "staff" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	"name" text NOT NULL,
	"phone" text DEFAULT '' NOT NULL,
	"user_id" text,
	"commission_pct" numeric(5, 2) DEFAULT 0 NOT NULL,
	"monthly_target" numeric(14, 2) DEFAULT 0 NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	CONSTRAINT "staff_org_id_id" UNIQUE("org_id","id")
);
